<script setup>
import { Head, Link, router } from '@inertiajs/vue3';
import { computed, nextTick, onMounted } from 'vue';
import OwnerLayout from '../../../Layouts/OwnerLayout.vue';

const props = defineProps({ date: String, timezone: String, bookings: Array, refundBookings: Array, courtBlocks: Array, calendar: Object });
const money = new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP' });
const summary = computed(() => ({
    total: props.bookings.length,
    confirmed: props.bookings.filter((booking) => booking.status === 'confirmed').length,
    holds: props.bookings.filter((booking) => booking.status === 'hold').length,
    paid: props.bookings.filter((booking) => booking.payment_status_value === 'paid').length,
    value: props.bookings.filter((booking) => booking.status !== 'cancelled' && booking.status !== 'expired').reduce((sum, booking) => sum + Number(booking.total_amount), 0),
}));
const refundBookings = computed(() => props.refundBookings || []);
const schedule = computed(() => {
    const groups = {};
    const add = (entry, kind) => {
        const key = `${entry.venue}|${entry.resource}`;
        groups[key] ||= { key, venue: entry.venue, resource: entry.resource, sport: entry.sport, entries: [] };
        groups[key].entries.push({ ...entry, kind });
    };

    props.bookings.forEach((booking) => add(booking, 'booking'));
    props.courtBlocks.forEach((block) => add(block, 'block'));

    return Object.values(groups).map((group) => ({
        ...group,
        entries: group.entries.sort((a, b) => a.start_time.localeCompare(b.start_time)),
    }));
});

function showDate(date) { router.get('/owner/bookings', { date }, { preserveScroll: true, preserveState: true }); }
function changeDate(event) { showDate(event.target.value); }
function changeMonth(date) { showDate(date); }
function calendarDayLabel(day) {
    const parts = [day.date];
    if (day.booking_count) parts.push(`${day.booking_count} booking${day.booking_count === 1 ? '' : 's'}`);
    if (day.block_count) parts.push(`${day.block_count} court block${day.block_count === 1 ? '' : 's'}`);
    return parts.join(', ');
}
function removeBlock(block) { if (window.confirm(`Reopen ${block.resource} ${block.is_all_day ? 'for the whole day' : `from ${block.start_time} to ${block.end_time}`}?`)) router.delete(`/owner/bookings/blocks/${block.id}`); }
function cancelBooking(booking) { const reason = window.prompt(`Why is ${booking.reference} being cancelled? (optional)`, ''); if (reason !== null) router.patch(`/owner/bookings/${booking.id}/cancel`, { cancellation_reason: reason || null }); }
function updatePayment(booking, status) { const labels = { paid: 'mark this payment paid', failed: 'record payment failure', cancelled: 'cancel this payment', refunded: 'record a full manual refund' }; const note = window.prompt(`Add a note to ${labels[status]}${status === 'refunded' ? ' (required)' : ' (optional)'}.`, ''); if (note !== null && (status !== 'refunded' || note.trim())) router.patch(`/owner/bookings/${booking.id}/payment`, { status, note: note || null }); }
function approveRefund(booking, retry = false) { const note = window.prompt(`${retry ? 'Retry' : 'Approve'} the full ${booking.refund_request.currency} ${booking.refund_request.amount} refund? Add an optional note.`, ''); if (note !== null) router.post(`/owner/refunds/${booking.refund_request.id}/${retry ? 'retry' : 'approve'}`, { note: note || null }); }
function rejectRefund(booking) { const note = window.prompt('Why is this refund request being declined? A clear response is required.', ''); if (note?.trim()) router.post(`/owner/refunds/${booking.refund_request.id}/reject`, { note: note.trim() }); }
function statusClass(status) { return { confirmed: 'bg-court-100 text-court-800 border-court-200', hold: 'bg-amber-100 text-amber-800 border-amber-200', cancelled: 'bg-red-50 text-red-700 border-red-100', expired: 'bg-slate-100 text-slate-500 border-slate-200' }[status] || 'bg-slate-100 text-slate-600 border-slate-200'; }

onMounted(async () => {
    if (!window.location.hash.startsWith('#refund-request-')) return;

    await nextTick();
    const refundRequest = document.getElementById(window.location.hash.slice(1));
    refundRequest?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    refundRequest?.focus({ preventScroll: true });
});
</script>

<template>
    <Head title="Bookings" />
    <OwnerLayout>
        <div class="mx-auto max-w-[92rem] space-y-7">
            <div class="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p class="eyebrow">Today</p><h2 class="mt-2 text-3xl font-semibold tracking-[-0.035em] text-slate-950 sm:text-4xl">Bookings</h2><p class="mt-2 text-sm text-slate-500">All times shown in {{ timezone }}.</p></div><div class="flex flex-col gap-2 sm:flex-row"><Link href="/owner/court-closures/create" class="rounded-xl border border-red-300 bg-red-50 px-5 py-3 text-center text-sm font-semibold text-red-800">Emergency closure</Link><Link href="/owner/bookings/blocks/create" class="rounded-xl border border-court-700 bg-white px-5 py-3 text-center text-sm font-semibold text-court-800">Block court time</Link><Link href="/owner/bookings/create" class="rounded-xl bg-court-700 px-5 py-3 text-center text-sm font-semibold text-white">+ Create booking</Link></div></div>

            <div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><section class="metric-card"><p class="text-sm text-slate-500">Today’s bookings</p><p class="mt-3 text-3xl font-semibold">{{ summary.total }}</p></section><section class="metric-card"><p class="text-sm text-slate-500">Confirmed</p><p class="mt-3 text-3xl font-semibold text-court-700">{{ summary.confirmed }}</p></section><section class="metric-card"><p class="text-sm text-slate-500">Held for now</p><p class="mt-3 text-3xl font-semibold text-amber-700">{{ summary.holds }}</p></section><section class="metric-card"><p class="text-sm text-slate-500">Paid bookings</p><p class="mt-3 text-3xl font-semibold">{{ summary.paid }}</p></section><section class="metric-card"><p class="text-sm text-slate-500">Value of today’s bookings</p><p class="mt-3 text-3xl font-semibold">{{ money.format(summary.value) }}</p></section></div>

            <section v-if="refundBookings.length" id="refund-requests" class="app-card overflow-hidden">
                <div class="border-b border-slate-100 px-5 py-5 sm:px-6"><p class="eyebrow">Action required</p><h3 class="mt-1 text-xl font-semibold">Refund requests <span class="text-slate-400">({{ refundBookings.length }})</span></h3><p class="mt-2 text-sm text-slate-500">Review these requests independently of the selected schedule date. Approval releases a future court slot and securely submits a full refund to the original payment provider.</p></div>
                <div class="divide-y divide-slate-100">
                    <article v-for="booking in refundBookings" :id="`refund-request-${booking.refund_request.id}`" :key="booking.refund_request.id" tabindex="-1" class="grid scroll-mt-6 gap-4 px-5 py-5 outline-none target:bg-amber-50/60 target:ring-2 target:ring-inset target:ring-amber-300 sm:px-6 lg:grid-cols-[1fr_auto] lg:items-center">
                        <div><div class="flex flex-wrap items-center gap-2"><h4 class="font-semibold">{{ booking.customer_name }} · {{ booking.reference }}</h4><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-700">{{ booking.refund_request.status_label }}</span><span v-if="booking.refund_request.requires_review" class="rounded-full bg-amber-100 px-2.5 py-1 text-xs font-semibold text-amber-800">Platform review required</span></div><p class="mt-1 text-sm text-slate-600">{{ booking.venue }} · {{ booking.resource }} · {{ money.format(Number(booking.refund_request.amount)) }}</p><p class="mt-3 rounded-xl bg-slate-50 px-4 py-3 text-sm text-slate-700"><strong>Player reason:</strong> {{ booking.refund_request.reason }}</p><p v-if="booking.refund_request.reviewer_note" class="mt-2 text-xs text-slate-500"><strong>Venue note:</strong> {{ booking.refund_request.reviewer_note }}</p><p v-if="booking.refund_request.failure_message" class="mt-2 text-xs text-red-700">{{ booking.refund_request.failure_message }}</p><p class="mt-2 text-[10px] text-slate-400">{{ booking.refund_request.reference }}</p></div>
                        <div class="flex flex-wrap gap-2 lg:justify-end"><button v-if="booking.refund_request.can_approve" type="button" class="rounded-xl bg-court-700 px-4 py-2.5 text-sm font-semibold text-white" @click="approveRefund(booking)">Approve full refund</button><button v-if="booking.refund_request.can_reject" type="button" class="rounded-xl border border-red-200 px-4 py-2.5 text-sm font-semibold text-red-700" @click="rejectRefund(booking)">Decline</button><button v-if="booking.refund_request.can_retry" type="button" class="rounded-xl border border-court-700 px-4 py-2.5 text-sm font-semibold text-court-800" @click="approveRefund(booking, true)">Retry refund</button></div>
                    </article>
                </div>
            </section>

            <section class="app-card overflow-hidden"><div class="flex flex-col gap-4 border-b border-slate-100 px-5 py-5 sm:px-6 lg:flex-row lg:items-center lg:justify-between"><div><p class="eyebrow">Court schedule</p><h3 class="mt-1 text-xl font-semibold">{{ calendar.label }}</h3><p class="mt-1 text-sm text-slate-500">Select a date to view its court schedule and booking details below.</p></div><div class="flex flex-wrap items-center gap-2"><button type="button" class="grid size-10 place-items-center rounded-xl border border-slate-300 text-lg font-semibold text-slate-700 hover:border-court-500 hover:text-court-700" aria-label="Previous month" @click="changeMonth(calendar.previous_date)">‹</button><button type="button" class="rounded-xl border border-slate-300 px-4 py-2.5 text-sm font-semibold text-slate-700 hover:border-court-500 hover:text-court-700" @click="showDate(calendar.today_date)">Today</button><button type="button" class="grid size-10 place-items-center rounded-xl border border-slate-300 text-lg font-semibold text-slate-700 hover:border-court-500 hover:text-court-700" aria-label="Next month" @click="changeMonth(calendar.next_date)">›</button><label><span class="sr-only">Schedule date</span><input type="date" :value="date" class="rounded-xl border-slate-300 text-sm" @change="changeDate"></label></div></div>
                <div class="px-3 py-4 sm:px-6 sm:py-6"><div class="mb-3 grid grid-cols-7 text-center text-[11px] font-semibold uppercase tracking-[0.12em] text-slate-400"><span v-for="weekday in ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']" :key="weekday" class="py-2">{{ weekday }}</span></div><div class="grid grid-cols-7 overflow-hidden rounded-2xl border border-slate-200 bg-slate-200"><template v-for="(week, weekIndex) in calendar.weeks" :key="weekIndex"><button v-for="day in week" :key="day.date" type="button" :aria-label="calendarDayLabel(day)" :class="['relative min-h-24 border-b border-r border-slate-200 bg-white p-2 text-left transition last:border-r-0 sm:min-h-28 sm:p-3', !day.is_current_month && 'bg-slate-50 text-slate-400', day.is_selected && 'z-10 bg-court-50 ring-2 ring-inset ring-court-600', 'hover:bg-court-50']" @click="showDate(day.date)"><div class="flex items-start justify-between gap-1"><span :class="['grid size-7 place-items-center rounded-full text-sm font-semibold', day.is_today ? 'bg-court-700 text-white' : day.is_selected ? 'bg-court-100 text-court-800' : 'text-slate-700']">{{ day.day }}</span><span v-if="day.booking_count" class="rounded-full bg-slate-900 px-1.5 py-0.5 text-[10px] font-semibold text-white">{{ day.booking_count }}</span></div><div class="mt-3 flex flex-wrap gap-1"><span v-if="day.confirmed_count" class="rounded-full bg-court-600 px-1.5 py-0.5 text-[10px] font-semibold text-white">{{ day.confirmed_count }} confirmed</span><span v-if="day.hold_count" class="rounded-full bg-amber-100 px-1.5 py-0.5 text-[10px] font-semibold text-amber-800">{{ day.hold_count }} hold</span><span v-if="day.block_count" class="rounded-full bg-slate-700 px-1.5 py-0.5 text-[10px] font-semibold text-white">{{ day.block_count }} block</span></div></button></template></div><div class="mt-4 flex flex-wrap gap-x-4 gap-y-2 text-xs text-slate-500"><span class="inline-flex items-center gap-1.5"><i class="size-2 rounded-full bg-court-600"></i>Confirmed</span><span class="inline-flex items-center gap-1.5"><i class="size-2 rounded-full bg-amber-400"></i>Held</span><span class="inline-flex items-center gap-1.5"><i class="size-2 rounded-full bg-slate-700"></i>Court block</span><span class="inline-flex items-center gap-1.5"><i class="size-2 rounded-full bg-slate-900"></i>Total bookings</span></div></div>
                <div class="border-t border-slate-100 px-5 py-4 sm:px-6"><p class="text-sm font-semibold text-slate-800">{{ date }}</p><p v-if="schedule.length" class="mt-1 text-sm text-slate-500">{{ bookings.length }} booking{{ bookings.length === 1 ? '' : 's' }} and {{ courtBlocks.length }} court block{{ courtBlocks.length === 1 ? '' : 's' }} selected.</p><p v-else class="mt-1 text-sm text-slate-500">No bookings or court blocks on this date.</p></div>
            </section>

            <section v-if="courtBlocks.length" class="app-card overflow-hidden"><div class="border-b border-slate-100 px-5 py-5 sm:px-6"><p class="eyebrow">Unavailable time</p><h3 class="mt-1 text-xl font-semibold">Court blocks <span class="text-slate-400">({{ courtBlocks.length }})</span></h3></div><div class="divide-y divide-slate-100"><article v-for="block in courtBlocks" :key="block.id" class="grid gap-4 px-5 py-5 sm:px-6 lg:grid-cols-[8rem_1fr_auto] lg:items-center"><div class="rounded-xl bg-slate-800 px-3 py-3 text-center text-white"><p class="font-semibold">{{ block.start_time }}</p><p v-if="block.end_time" class="mt-1 text-xs text-slate-300">to {{ block.end_time }}</p><p v-else class="mt-1 text-xs text-slate-300">until reopened</p></div><div><div class="flex flex-wrap items-center gap-2"><h4 class="font-semibold">{{ block.resource }}</h4><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-600">Booking disabled</span><span v-if="block.is_emergency_closure" class="rounded-full bg-red-100 px-2.5 py-1 text-xs font-semibold text-red-800">Emergency {{ block.closure_reference }}</span><span v-if="block.is_recurring" class="rounded-full bg-court-50 px-2.5 py-1 text-xs font-semibold text-court-800">Recurring</span></div><p class="mt-1 text-sm text-slate-600">{{ block.venue }} · {{ block.sport }}</p><p class="mt-3 rounded-lg bg-amber-50 px-3 py-2 text-sm text-amber-900"><strong>Reason:</strong> {{ block.reason }}</p><p v-if="block.created_by" class="mt-2 text-xs text-slate-400">Blocked by {{ block.created_by }}</p></div><Link v-if="block.is_emergency_closure" href="/owner/court-closures" class="rounded-xl border border-court-700 px-4 py-2.5 text-center text-sm font-semibold text-court-800">Manage closure</Link><button v-else-if="block.can_remove" type="button" class="rounded-xl border border-court-700 px-4 py-2.5 text-sm font-semibold text-court-800" @click="removeBlock(block)">Reopen time</button></article></div></section>

            <section class="app-card overflow-hidden"><div class="border-b border-slate-100 px-5 py-5 sm:px-6"><h3 class="text-xl font-semibold">Booking details <span class="text-slate-400">({{ bookings.length }})</span></h3></div><div v-if="bookings.length" class="divide-y divide-slate-100"><article v-for="booking in bookings" :key="booking.id" class="grid gap-4 px-5 py-5 lg:grid-cols-[6rem_1fr_auto] lg:items-start lg:px-6"><div class="rounded-xl bg-slate-950 px-3 py-3 text-center text-white"><p class="text-lg font-semibold">{{ booking.start_time }}</p><p class="mt-1 text-xs text-slate-400">to {{ booking.end_time }}</p></div><div><div class="flex flex-wrap items-center gap-2"><h4 class="font-semibold">{{ booking.customer_name }}</h4><span :class="['rounded-full border px-2.5 py-1 text-xs font-semibold', statusClass(booking.status)]">{{ booking.status_label }}</span></div><p class="mt-1 text-sm text-slate-600">{{ booking.venue }} · {{ booking.resource }} · {{ booking.sport }}</p><p class="mt-2 text-xs text-slate-400">{{ booking.reference }} · {{ booking.source }}<span v-if="booking.created_by"> · added by {{ booking.created_by }}</span></p><p v-if="booking.customer_phone || booking.customer_email" class="mt-2 text-xs text-slate-500"><span v-if="booking.customer_phone">{{ booking.customer_phone }}</span><span v-if="booking.customer_phone && booking.customer_email"> · </span><span>{{ booking.customer_email }}</span></p><p v-if="booking.promotion_title" class="mt-3 rounded-lg bg-amber-50 px-3 py-2 text-xs font-medium text-amber-800">{{ booking.promotion_title }} · total court savings {{ money.format(booking.discount_amount) }}</p><p v-if="booking.payment_requires_review" class="mt-3 rounded-lg bg-amber-50 px-3 py-2 text-xs font-medium text-amber-800">Please check payment: {{ booking.payment_review_reason }}</p></div><div class="flex flex-wrap items-center gap-2 lg:max-w-64 lg:justify-end"><div class="mr-auto lg:mr-0 lg:w-full lg:text-right"><p class="font-semibold">{{ money.format(booking.total_amount) }}</p><p class="mt-1 text-xs text-slate-400">Court price</p><p v-if="Number(booking.platform_service_fee_amount) > 0" class="mt-1 text-xs text-court-700">Player paid {{ money.format(booking.player_total_amount) }} including {{ money.format(booking.platform_service_fee_amount) }} FinACourt fee</p><p class="mt-1 text-xs text-slate-400">{{ booking.payment_mode || 'Payment type not set' }} · {{ booking.payment_status || 'Payment not recorded' }}</p></div><button v-if="booking.can_mark_paid" type="button" class="rounded-lg bg-court-50 px-3 py-2 text-xs font-semibold text-court-800" @click="updatePayment(booking, 'paid')">Mark paid</button><button v-if="booking.can_mark_failed" type="button" class="rounded-lg bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-800" @click="updatePayment(booking, 'failed')">Payment failed</button><button v-if="booking.can_refund" type="button" class="rounded-lg bg-slate-100 px-3 py-2 text-xs font-semibold text-slate-700" @click="updatePayment(booking, 'refunded')">Record refund</button><button v-if="booking.can_cancel" type="button" class="rounded-lg px-3 py-2 text-xs font-semibold text-red-600 hover:bg-red-50" @click="cancelBooking(booking)">Cancel</button></div></article></div><div v-else class="px-6 py-12 text-center text-sm text-slate-500">No bookings for this date.</div></section>
        </div>
    </OwnerLayout>
</template>
